xpath.script:
                document.addEventListener("DOMContentLoaded", function () {
                    var chatBubble = document.getElementById("wexPortalChatBubble");
                    var chatPopup = document.getElementById("wexPortalChatPopup");
                    var chatPopupPanel = document.getElementById("wexPortalChatPopupPanel");
                    var chatStatusBadge = document.getElementById("wexPortalChatPopupStatusBadge");
                    var chatResponsible = document.getElementById("wexPortalChatPopupResponsible");
                    var chatStream = document.getElementById("wexPortalChatPopupStream");
                    var chatSyncState = document.getElementById("wexPortalChatPopupSyncState");
                    var chatJumpButton = document.getElementById("wexPortalChatPopupJump");
                    var chatComposer = document.getElementById("portal_popup_conversation_body");
                    var chatCloseButtons = document.querySelectorAll("[data-wex-portal-chat-close]");
                    var debugNode = document.getElementById("wexPortalChatJsDebug");
                    var pollTimer = null;
                    var lastConversationSignature = "";
                    var lastKnownScrollHeight = 0;

                    function debug(message) {
                        if (debugNode) {
                            debugNode.textContent = "estado js: " + message;
                        }
                    }

                    function escapeHtml(value) {
                        var node = document.createElement("div");
                        node.textContent = value || "";
                        return node.innerHTML;
                    }

                    function buildConversationSignature(payload) {
                        return [
                            payload.message_count || 0,
                            payload.last_message_id || 0,
                            payload.last_message_date || "",
                            payload.state || "",
                            payload.responsible_name || "",
                        ].join("|");
                    }

                    function setSyncState(message) {
                        if (chatSyncState) {
                            chatSyncState.textContent = message || "";
                        }
                    }

                    function isNearBottom() {
                        if (!chatStream) {
                            return true;
                        }
                        var threshold = 72;
                        return chatStream.scrollHeight - chatStream.scrollTop - chatStream.clientHeight <= threshold;
                    }

                    function setJumpButtonVisible(visible) {
                        if (!chatJumpButton) {
                            return;
                        }
                        chatJumpButton.classList.toggle("is-visible", Boolean(visible));
                    }

                    function scrollConversationToBottom() {
                        if (!chatStream) {
                            return;
                        }
                        chatStream.scrollTop = chatStream.scrollHeight;
                        lastKnownScrollHeight = chatStream.scrollHeight;
                        setJumpButtonVisible(false);
                    }

                    function renderPopupMessages(payload, options) {
                        options = options || {};
                        if (!chatStream) {
                            return;
                        }
                        var shouldStickToBottom = options.force || isNearBottom();
                        var html = "";
                        var messages = payload.messages || [];
                        if (!messages.length) {
                            html = [
                                '
',
                                '  
',
                                '  
Aún no hay mensajes en esta conversación',
                                "",
                            ].join("");
                        } else {
                            messages.forEach(function (item) {
                                if (item.type === "date_separator") {
                                    html += [
                                        '
',
                                        "  " + escapeHtml(item.label) + "",
                                        "",
                                    ].join("");
                                    return;
                                }
                                if (item.type !== "message") {
                                    return;
                                }
                                var rowClass = item.is_customer ? "is-customer" : "is-technician";
                                var authorName = escapeHtml(item.author_name || "?");
                                var authorInitial = escapeHtml((item.author_name || "?").slice(0, 1));
                                html += [
                                    '
',
                                    '  
' + authorInitial + "",
                                    '  
',
                                    '    
',
                                    "      " + authorName + "",
                                    "      " + escapeHtml(item.created_at_label || "") + "",
                                    "    ",
                                    '    
' + escapeHtml(item.body || "") + "",
                                    "  ",
                                    "",
                                ].join("");
                            });
                        }
                        chatStream.innerHTML = html;
                        if (shouldStickToBottom) {
                            scrollConversationToBottom();
                        } else {
                            setJumpButtonVisible(chatStream.scrollHeight > lastKnownScrollHeight);
                            lastKnownScrollHeight = chatStream.scrollHeight;
                        }
                    }

                    function renderPopupHeader(payload) {
                        if (chatStatusBadge) {
                            chatStatusBadge.className = "wex_portal_chat_badge " + (payload.status_badge_class || "is-muted");
                            chatStatusBadge.textContent = payload.state_label || "";
                        }
                        if (chatResponsible) {
                            if (payload.responsible_name) {
                                var avatarHtml = payload.responsible_avatar_url
                                    ? ''
                                    : '' + escapeHtml(payload.responsible_initial || "?") + "";
                                chatResponsible.innerHTML =
                                    avatarHtml +
                                    '' +
                                    "" + escapeHtml(payload.responsible_name) + "" +
                                    "";
                                chatResponsible.style.display = "";
                            } else {
                                chatResponsible.innerHTML = "";
                                chatResponsible.style.display = "none";
                            }
                        }
                    }

                    function applyPopupPayload(payload, options) {
                        options = options || {};
                        var signature = buildConversationSignature(payload);
                        if (!options.force && signature === lastConversationSignature) {
                            setSyncState("Sin cambios recientes");
                            return;
                        }
                        lastConversationSignature = signature;
                        renderPopupHeader(payload);
                        renderPopupMessages(payload, options);
                        setSyncState(options.force ? "Conversación actualizada" : "Nuevo mensaje recibido");
                        debug(options.force ? "popup sincronizado" : "popup actualizado");
                    }

                    function refreshPopupConversation(options) {
                        options = options || {};
                        if (!chatPopup || !chatPopup.dataset.liveUrl) {
                            return Promise.resolve();
                        }
                        if (options.force) {
                            setSyncState("Actualizando conversación...");
                        }
                        return window.fetch(chatPopup.dataset.liveUrl, {
                            headers: {
                                "X-Requested-With": "XMLHttpRequest",
                            },
                            credentials: "same-origin",
                        }).then(function (response) {
                            if (!response.ok) {
                                throw new Error("HTTP " + response.status);
                            }
                            return response.json();
                        }).then(function (payload) {
                            applyPopupPayload(payload, options);
                        }).catch(function (error) {
                            setSyncState("No se pudo actualizar ahora mismo");
                            debug("error sync: " + error.message);
                        });
                    }

                    function startPopupPolling() {
                        if (pollTimer) {
                            return;
                        }
                        pollTimer = window.setInterval(function () {
                        if (chatPopup && chatPopup.classList.contains("is-open")) {
                                refreshPopupConversation();
                            }
                        }, 2500);
                        debug("polling activo");
                    }

                    function stopPopupPolling() {
                        if (!pollTimer) {
                            return;
                        }
                        window.clearInterval(pollTimer);
                        pollTimer = null;
                    }

                    function openPopup() {
                        if (!chatPopup) {
                            debug("popup no encontrado");
                            return;
                        }
                        chatPopup.classList.add("is-open");
                        document.body.classList.add("wex-portal-chat-open");
                        var url = new URL(window.location.href);
                        url.searchParams.set("open_portal_chat", "1");
                        url.hash = "portalRepairChatPopup";
                        window.history.replaceState({}, "", url.toString());
                        var composer = document.getElementById("portal_popup_conversation_body");
                        if (composer) {
                            window.setTimeout(function () {
                                composer.focus();
                            }, 120);
                        }
                        refreshPopupConversation({ force: true });
                        startPopupPolling();
                        debug("popup abierto");
                    }

                    function closePopup() {
                        if (!chatPopup) {
                            return;
                        }
                        chatPopup.classList.remove("is-open");
                        document.body.classList.remove("wex-portal-chat-open");
                        var url = new URL(window.location.href);
                        url.searchParams.delete("open_portal_chat");
                        if (url.hash === "#portalRepairChatPopup") {
                            url.hash = "";
                        }
                        window.history.replaceState({}, "", url.toString());
                        stopPopupPolling();
                        setJumpButtonVisible(false);
                        setSyncState("");
                        debug("popup cerrado");
                    }

                    if (chatBubble) {
                        chatBubble.addEventListener("click", function (event) {
                            event.preventDefault();
                            openPopup();
                        });
                    }

                    chatCloseButtons.forEach(function (button) {
                        button.addEventListener("click", function (event) {
                            event.preventDefault();
                            closePopup();
                        });
                    });

                    if (chatPopup) {
                        chatPopup.addEventListener("click", function (event) {
                            if (event.target === chatPopup) {
                                closePopup();
                            }
                        });
                    }

                    if (chatStream) {
                        chatStream.addEventListener("scroll", function () {
                            if (isNearBottom()) {
                                setJumpButtonVisible(false);
                            }
                        });
                    }

                    if (chatJumpButton) {
                        chatJumpButton.addEventListener("click", function () {
                            scrollConversationToBottom();
                            if (chatComposer) {
                                chatComposer.focus();
                            }
                        });
                    }

                    document.addEventListener("keydown", function (event) {
                        if (event.key === "Escape" && chatPopup && chatPopup.classList.contains("is-open")) {
                            closePopup();
                        }
                    });

                    if (
                        new URLSearchParams(window.location.search).get("open_portal_chat") === "1" ||
                        window.location.hash === "#portalRepairChatPopup"
                    ) {
                        openPopup();
                    } else if (debugNode) {
                        debug("js inline inicializado");
                    }
                });
